<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { artBatchDisplayKey, type ArtBatchDisplayItem } from '../domain/art-prototype-presentation'
const props = withDefaults(defineProps<{ open: boolean; planKey: string; items: readonly ArtBatchDisplayItem[]; mode?: 'produce' | 'retry'; busy?: boolean; executionAvailable?: boolean; blockedReason?: string }>(), { mode: 'produce', busy: false, executionAvailable: false, blockedReason: '' })
const emit = defineEmits<{ 'update:open': [value: boolean]; confirm: [value: { planKey: string; mode: 'produce' | 'retry'; approved: true }] }>()
const confirmed = ref(false), displayKey = computed(() => artBatchDisplayKey(props.planKey, props.mode, props.items))
watch([displayKey, () => props.open, () => props.executionAvailable, () => props.busy, () => props.blockedReason], () => { confirmed.value = false }, { flush: 'sync' })
const available = computed(() => !!props.planKey && props.executionAvailable && !props.busy && !props.blockedReason && props.items.length > 0 && props.items.every(item => item.executable))
function submit() { if (!available.value || !confirmed.value) return; emit('confirm', { planKey: props.planKey, mode: props.mode, approved: true }); confirmed.value = false }
</script>
<template><el-dialog :model-value="open" title="核对批量生产" width="min(700px, calc(100vw - 28px))" :close-on-click-modal="false" :close-on-press-escape="!busy" :show-close="!busy" @update:model-value="!busy && emit('update:open', $event)"><section data-testid="art-batch-production-confirm"><p>{{ mode === 'retry' ? '重试明确失败项' : '批量生产' }} {{ items.length }} 项</p><ul><li v-for="item in items" :key="item.id"><strong>{{ item.name }}</strong> · {{ item.specName }} v{{ item.specVersion }} · {{ item.width }} × {{ item.height }}<p v-if="!item.executable" role="status">{{ item.reason || '当前输入或能力尚未核对，不提交此项。' }}</p></li></ul><p v-if="!executionAvailable" role="status">当前生产能力尚未接通；创建准备任务不等于生成成功。</p><p v-if="blockedReason" role="status">{{ blockedReason }}</p><p>运行中、结果未知及规格待核对项不能重复提交；结果未知时停止后续项，保留原操作核对。</p><label class="batch-check"><input v-model="confirmed" type="checkbox" :disabled="!available" data-testid="batch-approved">已核对这些需求、规格版本和统一尺寸</label><div class="batch-actions"><button type="button" :disabled="busy" @click="emit('update:open', false)">返回修改</button><button type="button" :disabled="!available || !confirmed" data-testid="batch-submit" @click="submit">{{ mode === 'retry' ? '重试明确失败项' : '开始生产' }}</button></div></section></el-dialog></template>
<style scoped>.batch-check,.batch-actions{display:flex;align-items:center;gap:10px;margin-top:14px}.batch-actions{justify-content:flex-end}li{margin:10px 0;line-height:1.7}p{line-height:1.7;overflow-wrap:anywhere}.batch-actions button{font:inherit;padding:8px 12px;border:1px solid var(--el-border-color);border-radius:6px;background:var(--el-bg-color)}button:disabled{opacity:.5;cursor:not-allowed}:focus-visible{outline:2px solid var(--el-color-primary);outline-offset:2px}</style>
